import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { view9Schema, type View9 } from "./view9.js";

/** The privacy settings of the event. */
export type StreamPrivacy2 = {
  /**
   * The initial privacy of the videos generated by streaming to the event as well as the embed
   * privacy of the entire collection.
   *
   * Option descriptions:
   *  * `anybody` - Anyone can access the event. This privacy setting appears as `Public` on the
   *    Vimeo front end.
   *  * `embed_only` - The event doesn't appear on Vimeo, but it can be embedded on other sites.
   *  * `nobody` - No one except the owner can access the event. This privacy setting appears as
   *    `Private` on the Vimeo front end.
   *  * `password` - Only those with the password can access the event.
   *  * `team` - Anyone on this team can access the event. This privacy setting appears as `Company
   *    only` on the Vimeo front end.
   *  * `unlisted` - Only those with the private link can access the event.
   */
  view?: View9;
};

export const streamPrivacy2Schema: Schema<StreamPrivacy2> = s.object<StreamPrivacy2>({
  view: s.optional(s.lazy(() => view9Schema)),
});
